-- 030_live_results_statistics.sql
--
-- The live statistics of LOOP_SPEC v6.2 section 7.4 on trading.live_results (T-8a commit (12b);
-- COLUMN_PLAN section 2.6, where this migration is numbered 024), and the six overlay columns HD
-- ruled on 2026-10-10. Twenty columns, every one NULL-able with no default:
--   the worst day          worst_day_date, worst_day_symbol (worst_day exists)
--   on the sizing capital  max_drawdown_sizing, volatility_sizing, worst_day_sizing,
--                          worst_day_sizing_date, worst_day_sizing_symbol   (futures rows only)
--   the months, the years  monthly_skew, monthly_tail_ratio, calendar_year_returns (jsonb),
--                          losing_years
--   the fill counts        total_trades, total_strategy_fills, total_roll_fills (cumulative)
--   the overlay's readings overlay_risk, overlay_risk_jump, overlay_risk_shock,
--                          overlay_gross_leverage, overlay_net_leverage, var_95_1d (futures rows)
-- The first fourteen are statistics through the last settled row: a run writes them on its own
-- row and refreshes them on the Day T-1 row. The six overlay columns describe the book a row
-- stores and are written once, by the run of the row's date.
--
-- NO BACKFILL (T-8D R32: history is never rewritten): every existing row keeps NULL in all
-- twenty, and each comment says so.
--
-- SAFETY: ADD COLUMN of NULL-able columns with no default is metadata-only; no existing column,
-- value, key, index or view is touched; type-guarded; transactional and idempotent.

BEGIN;
DO $$
DECLARE
    want CONSTANT text[][] := ARRAY[
        ['worst_day_date', 'date'],
        ['worst_day_symbol', 'text'],
        ['max_drawdown_sizing', 'numeric'],
        ['volatility_sizing', 'numeric'],
        ['worst_day_sizing', 'numeric'],
        ['worst_day_sizing_date', 'date'],
        ['worst_day_sizing_symbol', 'text'],
        ['monthly_skew', 'numeric'],
        ['monthly_tail_ratio', 'numeric'],
        ['calendar_year_returns', 'jsonb'],
        ['losing_years', 'integer'],
        ['total_trades', 'integer'],
        ['total_strategy_fills', 'integer'],
        ['total_roll_fills', 'integer'],
        ['overlay_risk', 'numeric'],
        ['overlay_risk_jump', 'numeric'],
        ['overlay_risk_shock', 'numeric'],
        ['overlay_gross_leverage', 'numeric'],
        ['overlay_net_leverage', 'numeric'],
        ['var_95_1d', 'numeric']];
    i int;
    found text;
BEGIN
    IF to_regclass('trading.live_results') IS NULL THEN RAISE EXCEPTION 'trading.live_results does not exist'; END IF;
    FOR i IN 1 .. array_length(want, 1) LOOP
        SELECT data_type INTO found FROM information_schema.columns
         WHERE table_schema = 'trading' AND table_name = 'live_results' AND column_name = want[i][1];
        IF found IS NOT NULL AND found <> want[i][2] THEN
            RAISE EXCEPTION 'trading.live_results.% exists with another type (%)', want[i][1], found;
        END IF;
    END LOOP;
END $$;
ALTER TABLE trading.live_results
    ADD COLUMN IF NOT EXISTS worst_day_date date,
    ADD COLUMN IF NOT EXISTS worst_day_symbol text,
    ADD COLUMN IF NOT EXISTS max_drawdown_sizing numeric,
    ADD COLUMN IF NOT EXISTS volatility_sizing numeric,
    ADD COLUMN IF NOT EXISTS worst_day_sizing numeric,
    ADD COLUMN IF NOT EXISTS worst_day_sizing_date date,
    ADD COLUMN IF NOT EXISTS worst_day_sizing_symbol text,
    ADD COLUMN IF NOT EXISTS monthly_skew numeric,
    ADD COLUMN IF NOT EXISTS monthly_tail_ratio numeric,
    ADD COLUMN IF NOT EXISTS calendar_year_returns jsonb,
    ADD COLUMN IF NOT EXISTS losing_years integer,
    ADD COLUMN IF NOT EXISTS total_trades integer,
    ADD COLUMN IF NOT EXISTS total_strategy_fills integer,
    ADD COLUMN IF NOT EXISTS total_roll_fills integer,
    ADD COLUMN IF NOT EXISTS overlay_risk numeric,
    ADD COLUMN IF NOT EXISTS overlay_risk_jump numeric,
    ADD COLUMN IF NOT EXISTS overlay_risk_shock numeric,
    ADD COLUMN IF NOT EXISTS overlay_gross_leverage numeric,
    ADD COLUMN IF NOT EXISTS overlay_net_leverage numeric,
    ADD COLUMN IF NOT EXISTS var_95_1d numeric;
COMMENT ON COLUMN trading.live_results.worst_day_date IS $c030$The date of worst_day: the first grid date that has the smallest grid return. NULL while the series has no return. Taken on the statistics grid described in the comment on the table (futures rows: the Sunday-to-Friday dates on which at least 9 symbols of the book's universe printed a bar, K = 311.0574 sessions a year; equity rows: the NYSE sessions, K = 252), from the book's start through the last settled row: the row a run writes carries the figure through the day before, and the next run refreshes it once the day is settled. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.worst_day_symbol IS $c030$The symbol whose P&L over the rows folded into the worst day's grid return (worst_day, worst_day_date) is the most negative; equal losses name the first symbol in text order; NULL when no symbol lost over those rows or the series has no return. The rows folded into a grid return are every stored date after the previous grid date through the return's own date (a Saturday or a holiday row lands in the next grid return), taken together. A symbol's P&L over them is the sum of trading.positions.daily_realized_pnl on those dates plus the change across them of trading.positions.daily_unrealized_pnl (the open position's unrealised level; 0 on every futures row, which books its whole daily move as realised), summed over the book's sleeves (a symbol two sleeves hold is the book's). It is the P&L of LOOP_SPEC section 6.6, before costs. Taken on the statistics grid described in the comment on the table (futures rows: the Sunday-to-Friday dates on which at least 9 symbols of the book's universe printed a bar, K = 311.0574 sessions a year; equity rows: the NYSE sessions, K = 252), from the book's start through the last settled row: the row a run writes carries the figure through the day before, and the next run refreshes it once the day is settled. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.max_drawdown_sizing IS $c030$Percentage points of the sizing capital, positive: the largest fall of the running SUM of r^s from its running peak (the sum and its peak start at 0). FUTURES rows only; NULL on equity rows, which store no sizing capital. r^s of a grid return = its dollar P&L (the difference of two grid levels, so the P&L of every folded row is in it) / E_t x 100, never compounded. E_t is risk_detail.sizing_capital of the last stored row on or before the grid date that carries one: the grid row's own where it has one; a folded Saturday or holiday row adds to the P&L and does not supply the capital of a grid row that has its own. The series starts at the first grid date that has such a capital (rows written before migration 020 carry none), so it can be shorter than the account series. NULL with fewer than 2 such returns. The account twin is max_drawdown (compounded, on the account value). Taken on the statistics grid described in the comment on the table (futures rows: the Sunday-to-Friday dates on which at least 9 symbols of the book's universe printed a bar, K = 311.0574 sessions a year; equity rows: the NYSE sessions, K = 252), from the book's start through the last settled row: the row a run writes carries the figure through the day before, and the next run refreshes it once the day is settled. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.volatility_sizing IS $c030$Percent, annualised, REALISED, on the sizing capital: the sample standard deviation (n - 1) of r^s x sqrt(K). FUTURES rows only; NULL on equity rows, which store no sizing capital. r^s of a grid return = its dollar P&L (the difference of two grid levels, so the P&L of every folded row is in it) / E_t x 100, never compounded. E_t is risk_detail.sizing_capital of the last stored row on or before the grid date that carries one: the grid row's own where it has one; a folded Saturday or holiday row adds to the P&L and does not supply the capital of a grid row that has its own. The series starts at the first grid date that has such a capital (rows written before migration 020 carry none), so it can be shorter than the account series. NULL with fewer than 2 such returns. The account twin is volatility; the forward figure is overlay_risk. Taken on the statistics grid described in the comment on the table (futures rows: the Sunday-to-Friday dates on which at least 9 symbols of the book's universe printed a bar, K = 311.0574 sessions a year; equity rows: the NYSE sessions, K = 252), from the book's start through the last settled row: the row a run writes carries the figure through the day before, and the next run refreshes it once the day is settled. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.worst_day_sizing IS $c030$Percent of the sizing capital: the smallest r^s. FUTURES rows only; NULL on equity rows, which store no sizing capital. r^s of a grid return = its dollar P&L (the difference of two grid levels, so the P&L of every folded row is in it) / E_t x 100, never compounded. E_t is risk_detail.sizing_capital of the last stored row on or before the grid date that carries one: the grid row's own where it has one; a folded Saturday or holiday row adds to the P&L and does not supply the capital of a grid row that has its own. The series starts at the first grid date that has such a capital (rows written before migration 020 carry none), so it can be shorter than the account series. NULL with fewer than 2 such returns. The account twin is worst_day. Taken on the statistics grid described in the comment on the table (futures rows: the Sunday-to-Friday dates on which at least 9 symbols of the book's universe printed a bar, K = 311.0574 sessions a year; equity rows: the NYSE sessions, K = 252), from the book's start through the last settled row: the row a run writes carries the figure through the day before, and the next run refreshes it once the day is settled. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.worst_day_sizing_date IS $c030$The date of worst_day_sizing: the first grid date that has the smallest r^s. NULL where worst_day_sizing is. Taken on the statistics grid described in the comment on the table (futures rows: the Sunday-to-Friday dates on which at least 9 symbols of the book's universe printed a bar, K = 311.0574 sessions a year; equity rows: the NYSE sessions, K = 252), from the book's start through the last settled row: the row a run writes carries the figure through the day before, and the next run refreshes it once the day is settled. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.worst_day_sizing_symbol IS $c030$The symbol whose P&L over the rows folded into the grid return of worst_day_sizing_date is the most negative; NULL where worst_day_sizing is, or when no symbol lost over those rows. The rows folded into a grid return are every stored date after the previous grid date through the return's own date (a Saturday or a holiday row lands in the next grid return), taken together. A symbol's P&L over them is the sum of trading.positions.daily_realized_pnl on those dates plus the change across them of trading.positions.daily_unrealized_pnl (the open position's unrealised level; 0 on every futures row, which books its whole daily move as realised), summed over the book's sleeves (a symbol two sleeves hold is the book's). It is the P&L of LOOP_SPEC section 6.6, before costs. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.monthly_skew IS $c030$A ratio. The sample skewness of the account's returns of its COMPLETE calendar months: the adjusted Fisher-Pearson coefficient G1 = n / ((n - 1)(n - 2)) x sum(((x - mean) / s)^3), s the sample standard deviation (n - 1). A month's return is compounded from its grid returns. A month is complete when its first calendar day is after the book's start and its last calendar day is on or before the last settled date (the month the book starts in and the current month are partial). NULL under 12 complete months. Taken on the statistics grid described in the comment on the table (futures rows: the Sunday-to-Friday dates on which at least 9 symbols of the book's universe printed a bar, K = 311.0574 sessions a year; equity rows: the NYSE sessions, K = 252), from the book's start through the last settled row: the row a run writes carries the figure through the day before, and the next run refreshes it once the day is settled. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.monthly_tail_ratio IS $c030$A ratio. Over the same complete calendar months as monthly_skew: the mean of the monthly returns at or above their 95th percentile divided by the absolute value of the mean of the monthly returns at or below their 5th percentile, the percentiles by linear interpolation between order statistics. NULL under 12 complete months, or when the lower mean is 0. Taken on the statistics grid described in the comment on the table (futures rows: the Sunday-to-Friday dates on which at least 9 symbols of the book's universe printed a bar, K = 311.0574 sessions a year; equity rows: the NYSE sessions, K = 252), from the book's start through the last settled row: the row a run writes carries the figure through the day before, and the next run refreshes it once the day is settled. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.calendar_year_returns IS $c030${"YYYY": {"return": percent, "partial": true or false}} on the account: each calendar year's return compounded from its grid returns. A year is full (partial false) when its 1 January is after the book's start and its 31 December is on or before the last settled date; a partial first or last year is shown and flagged. An empty object while the series has no return. Taken on the statistics grid described in the comment on the table (futures rows: the Sunday-to-Friday dates on which at least 9 symbols of the book's universe printed a bar, K = 311.0574 sessions a year; equity rows: the NYSE sessions, K = 252), from the book's start through the last settled row: the row a run writes carries the figure through the day before, and the next run refreshes it once the day is settled. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.losing_years IS $c030$The count of FULL calendar years of calendar_year_returns with a negative return; a partial first or last year is shown there and never counted here. Taken on the statistics grid described in the comment on the table (futures rows: the Sunday-to-Friday dates on which at least 9 symbols of the book's universe printed a bar, K = 311.0574 sessions a year; equity rows: the NYSE sessions, K = 252), from the book's start through the last settled row: the row a run writes carries the figure through the day before, and the next run refreshes it once the day is settled. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.total_trades IS $c030$Cumulative, from the book's start through the last settled date. ROUND TRIPS: the ACCOUNT's fills that reduce, close or flip a non-zero net position of the account in a contract (one tracker a contract; a one-contract trim counts once, as a full close does; a position under 1e-9 is flat). An account fill is the STRATEGY rows of trading.executions of one contract on one stored date, netted between the sleeves. ROLL and BORROW rows are never a trade: a roll is not a trading decision. Read from the book's trading.executions rows dated from its start (the metadata anchor); a position opened before the start is not tracked. The definition of backtest.results.total_trades. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.total_strategy_fills IS $c030$Cumulative, from the book's start through the last settled date. The ACCOUNT's STRATEGY fills AFTER NETTING BETWEEN SLEEVES, not the sleeve rows of trading.executions (those are unchanged: one row per sleeve with its netting_adjustment). Per contract and stored date the sleeves' STRATEGY rows are summed: a full cross is 0 fills (no execution happened), a partial offset is 1, two sleeves on the same side are 1, a single sleeve is 1, and a reversal through zero is one fill: a reversal stored as two same-side rows of one contract and date (the close, then the open) is one order the account sent, and the count is of account orders (HD 2026-10-10). On a book of one sleeve it equals the count of STRATEGY rows less one for each such reversal. Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.total_roll_fills IS $c030$Cumulative, from the book's start through the last settled date. The ROLL legs: the rows of trading.executions with execution_type ROLL (two a roll and sleeve), never netted, never a trade. 0 on equity rows. Executions = STRATEGY rows + ROLL legs (+ BORROW rows on the equity book). Rows written before migration 030 hold NULL. LOOP_SPEC v6.2 sections 7.4 and 10; migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.overlay_risk IS $c030$A fraction of the sizing capital, annualised, FORWARD: R = sqrt(x' Sigma x), the expected annual volatility of the stored book, Sigma the overlay's annualised covariance of the gate window (the last 252 dates, on the window's own bars a year). THE FIGURE TO COMPARE WITH THE RISK TARGET tau (CONSERVATIVE 0.20). LIMIT: R_max = 2.25 x tau (risk.json carver module and LOOP_SPEC v6.2 section 12 D1): 0.45 on CONSERVATIVE. COVERAGE: the figure covers the contracts inside the overlay's covariance that day; a contract with too short a history, or a held row that cannot be weighed, is outside R and inside the shock and leverage readings, so the figure understates the book on such a day. NULL also on a blind window (fewer than 21 complete dates; risk_detail.overlay_blind), where no covariance reading exists. FUTURES rows only, on the rows that carry risk_detail (a sized rebalance the overlay answered; one set a book, on the book's one row of the date); NULL on equity rows and on a row with no risk_detail (no session, a sizing hold, a refused overlay). The risk overlay's own reading (overlay::readings, no second implementation) of the book THIS ROW STORES, on the weights x_i = quantity x multiplier x raw close at the signal date / E_t, E_t = risk_detail.sizing_capital, over the day's gate window. Written once, by the run of the row's date; never refreshed. NOT the reporter's portfolio_var (price-weighted, no contract multiplier, not a risk) and not volatility (realised, on the account). LOOP_SPEC v6.2 sections 7.2 and 7.3 said the readings are never columns; HD's decision of 2026-10-10 stores them and governs. Rows written before migration 030 hold NULL. Migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.overlay_risk_jump IS $c030$A fraction of the sizing capital, annualised, FORWARD: R_jump = sqrt(x' Sigma_jump x), the window's correlations on each contract's own jump sigma in place of its window sigma. LIMIT: R_jump_max = 4.5 x tau (risk.json carver module and LOOP_SPEC v6.2 section 12 D1): 0.90 on CONSERVATIVE. COVERAGE: the figure covers the contracts inside the overlay's covariance that day; a contract with too short a history, or a held row that cannot be weighed, is outside R and inside the shock and leverage readings, so the figure understates the book on such a day. NULL also on a blind window. FUTURES rows only, on the rows that carry risk_detail (a sized rebalance the overlay answered; one set a book, on the book's one row of the date); NULL on equity rows and on a row with no risk_detail (no session, a sizing hold, a refused overlay). The risk overlay's own reading (overlay::readings, no second implementation) of the book THIS ROW STORES, on the weights x_i = quantity x multiplier x raw close at the signal date / E_t, E_t = risk_detail.sizing_capital, over the day's gate window. Written once, by the run of the row's date; never refreshed. NOT the reporter's jump_risk (a percentile of summed absolute weighted daily returns over the reporter's long window). LOOP_SPEC v6.2 sections 7.2 and 7.3 said the readings are never columns; HD's decision of 2026-10-10 stores them and governs. Rows written before migration 030 hold NULL. Migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.overlay_risk_shock IS $c030$A fraction of the sizing capital, annualised, FORWARD: R_shock = sum of |x_i| x sigma_i, each contract on its own window sigma, as if every correlation were 1. LIMIT: R_shock_max = 4.0 x tau (risk.json carver module and LOOP_SPEC v6.2 section 12 D1): 0.80 on CONSERVATIVE. It includes a contract whose history is too short for the covariance (on its own window sigma), so it covers more of the book than overlay_risk; a held row that cannot be weighed is in no reading. NULL also on a blind window. FUTURES rows only, on the rows that carry risk_detail (a sized rebalance the overlay answered; one set a book, on the book's one row of the date); NULL on equity rows and on a row with no risk_detail (no session, a sizing hold, a refused overlay). The risk overlay's own reading (overlay::readings, no second implementation) of the book THIS ROW STORES, on the weights x_i = quantity x multiplier x raw close at the signal date / E_t, E_t = risk_detail.sizing_capital, over the day's gate window. Written once, by the run of the row's date; never refreshed. The reporter has no namesake; it is not max_correlation (the reporter's largest pairwise correlation). LOOP_SPEC v6.2 sections 7.2 and 7.3 said the readings are never columns; HD's decision of 2026-10-10 stores them and governs. Rows written before migration 030 hold NULL. Migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.overlay_gross_leverage IS $c030$A multiple of the sizing capital, of today's stored book: L = sum of |x_i| over every contract the pass weighs. LIMIT: max_gross_leverage 8.0 (risk.json carver module and LOOP_SPEC v6.2 section 12 D1). Stored on a blind window too. FUTURES rows only, on the rows that carry risk_detail (a sized rebalance the overlay answered; one set a book, on the book's one row of the date); NULL on equity rows and on a row with no risk_detail (no session, a sizing hold, a refused overlay). The risk overlay's own reading (overlay::readings, no second implementation) of the book THIS ROW STORES, on the weights x_i = quantity x multiplier x raw close at the signal date / E_t, E_t = risk_detail.sizing_capital, over the day's gate window. Written once, by the run of the row's date; never refreshed. NOT the reporter's gross_leverage (NULL on futures rows) and not portfolio_leverage (gross_notional at the T-1 close over the ACCOUNT value): this one is on the sizing capital at the raw signal closes. LOOP_SPEC v6.2 sections 7.2 and 7.3 said the readings are never columns; HD's decision of 2026-10-10 stores them and governs. Rows written before migration 030 hold NULL. Migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.overlay_net_leverage IS $c030$A multiple of the sizing capital, SIGNED, of today's stored book: L_net = sum of x_i (a net short book is negative). LIMIT: max_net_leverage 6.0 (risk.json carver module and LOOP_SPEC v6.2 section 12 D1), applied to its ABSOLUTE value. Stored on a blind window too. FUTURES rows only, on the rows that carry risk_detail (a sized rebalance the overlay answered; one set a book, on the book's one row of the date); NULL on equity rows and on a row with no risk_detail (no session, a sizing hold, a refused overlay). The risk overlay's own reading (overlay::readings, no second implementation) of the book THIS ROW STORES, on the weights x_i = quantity x multiplier x raw close at the signal date / E_t, E_t = risk_detail.sizing_capital, over the day's gate window. Written once, by the run of the row's date; never refreshed. NOT net_leverage (net_notional at the T-1 close over the ACCOUNT value): this one is on the sizing capital at the raw signal closes. LOOP_SPEC v6.2 sections 7.2 and 7.3 said the readings are never columns; HD's decision of 2026-10-10 stores them and governs. Rows written before migration 030 hold NULL. Migration 030.$c030$;
COMMENT ON COLUMN trading.live_results.var_95_1d IS $c030$Dollars, positive, FORWARD: the one-day 95 percent value-at-risk of the stored book, 1.645 x overlay_risk / sqrt(the gate window's bars a year) x E_t (risk_detail.sizing_capital): the same covariance as overlay_risk, a normal one-sided 95 percent point, one trading day. No limit is read against it. COVERAGE: the figure covers the contracts inside the overlay's covariance that day; a contract with too short a history, or a held row that cannot be weighed, is outside R and inside the shock and leverage readings, so the figure understates the book on such a day. NULL where overlay_risk is. FUTURES rows only, on the rows that carry risk_detail (a sized rebalance the overlay answered; one set a book, on the book's one row of the date); NULL on equity rows and on a row with no risk_detail (no session, a sizing hold, a refused overlay). The risk overlay's own reading (overlay::readings, no second implementation) of the book THIS ROW STORES, on the weights x_i = quantity x multiplier x raw close at the signal date / E_t, E_t = risk_detail.sizing_capital, over the day's gate window. Written once, by the run of the row's date; never refreshed. NOT portfolio_var, which is not a value-at-risk. LOOP_SPEC v6.2 sections 7.2 and 7.3 said the readings are never columns; HD's decision of 2026-10-10 stores them and governs. Rows written before migration 030 hold NULL. Migration 030.$c030$;
COMMIT;
